import numpy as np
from scipy.optimize import minimize_scalar
def build2(w,H):
    cols=[np.ones_like(x),x,x**2,x**3,v,np.sin(x),np.cos(x),np.exp(-x)]
    for h in range(1,H+1):
        cols += [np.cos(h*w*t), np.sin(h*w*t)]
    return np.column_stack(cols)
def nm(w,H):
    X=build2(w,H); cf,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
    return np.mean((dv_dt-X@cf)**2)/np.var(dv_dt)
for H in [1,2,3]:
    r_=minimize_scalar(lambda w: nm(w,H),bounds=(0.12,0.14),method='bounded',options={'xatol':1e-10})
